conditions.leftValue:
={{ (() => {
  // Subject and body in lowercase for matching
  const subject = ($json.email_subject || "").toLowerCase();
  const body = ($json.email_body || "").toLowerCase();
  const combined = subject + " " + body;

  // Job recommendation digests are never real applications
  const isRecommendation =
    /job recommendations|recommended jobs|jobs you may like|jobs for you|recommended for you/i.test(subject);

  const patterns = [
    /application (has been )?received/,
    /we (have )?received your application/,
    /thank you for (your )?application/,
    /application confirmation/,
    /interview invitation/,
    /invite you to an interview/,
    /invited to an interview/,
    /interview scheduled/,
    /regret to inform you/,
    /not moving forward with your application/,
    /vielen dank für (deine|ihre) bewerbung/,
    /deine bewerbung.*(nicht weiter berücksichtigen|nicht berücksichtigen)/,
    /ihre bewerbung.*(nicht weiter berücksichtigen|nicht berücksichtigen)/,
    /leider mitteilen/,
    /zum vorstellungsgespräch/,
    /zu einem vorstellungsgespräch/,
    /wir haben deine bewerbung erhalten/,
    /wir haben ihre bewerbung erhalten/,
    /bewerbung ist eingegangen/
  ];

  return !isRecommendation && patterns.some(p => p.test(combined));
})() }}
